    ctx.closePath();
    ctx.fill();
    // Debris (rotating squares)
    ctx.fillStyle = '#888';
    debris.forEach(d => {
      ctx.save();
      ctx.translate(d.x, d.y);
      ctx.rotate(d.angle);
      ctx.fillRect(-d.r / 2, -d.r / 2, d.r, d.r);
      ctx.restore();
    });
    // Packets (blue circles)
